class Account(private val floor: Long) {
    init {
        require(floor >= 0) { "floor must be non-negative" }
    }

    var balance: Long = floor
        private set

    fun withdraw(amount: Long) {
        require(amount > 0) { "amount must be positive, was $amount" }
        val nextBalance = balance - amount
        check(nextBalance >= floor) { "invariant: $nextBalance < $floor" }
        balance = nextBalance
        check(balance >= floor) { "invariant: $balance < $floor" }
    }
}
